const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let user=null,current=null,todayId=null,library=[],mode='choice',reviewing=false,busy=false,authMode='login',bankTab='saved',chatId=null,chatMessages=[],chatBusy=false;
const settingsOpen=new Set();
let dailySlots=[],dailyDay=null,activeSlot=0,requestedSlot=0,requestedDay=null,settingsSaveQueue=Promise.resolve(),todayNeedsRefresh=false,editingTopicsOnly=false;
const heartIcon=saved=>`<span class="heart-icon" data-saved="${saved}" aria-hidden="true">❤️</span>`;
const shareIcon='<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><path d="m8.6 10.5 6.8-4m-6.8 7 6.8 4"/></svg>';
let guestToken=null,guestQuestion=null,guestBusy=false;
let setupDraft=null,resetToken=null,profileEditing=false;
let theme='dark';try{theme=localStorage.getItem('fancy-knowing-theme')||'dark'}catch{}
const loading=text=>`<div class="loading"><div class="spinner"></div>${esc(text)}</div>`;
function renderHeaderProfile(){const button=$('#headerprofile');button.hidden=!user;if(user)button.innerHTML=user.avatar?`<img src="${esc(user.avatar)}" alt="">`:`<span aria-hidden="true">${esc((user.profile?.name||'?').slice(0,1).toUpperCase())}</span>`}
function applyTheme(value){renderHeaderProfile();theme=value;FancyDesign.apply({...user?.settings,theme:value});try{localStorage.setItem('fancy-knowing-theme',value)}catch{}}
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').hidden=true,4000)}
async function api(path,options={}){
 let response;try{response=await fetch('/api'+path,{credentials:'same-origin',...options,headers:{...(options.body?{'Content-Type':'application/json'}:{}),...options.headers},body:options.body?JSON.stringify(options.body):undefined})}catch{throw new Error('Could not connect. Check your internet and try again.')}
 let data;try{data=await response.json()}catch{throw new Error('The backend is not connected at this address yet. Open the Cloudflare Worker address after setup.')}
 if(!response.ok){const e=new Error(data.error||'Something went wrong. Please try again.');e.status=response.status;if(response.status===401&&user){clearAccount();showAuth()}throw e}return data;
}
function clearAccount(){user=null;renderHeaderProfile();current=null;todayId=null;library=[];chatId=null;chatMessages=[];if($('#chat').open)$('#chat').close();$('#nav').hidden=true}
function page(name){['auth','today','bank','settings','onboarding','emailsetup'].forEach(p=>$('#'+p).hidden=p!==name);$('#nav').hidden=!user||['auth','onboarding','emailsetup'].includes(name);document.querySelectorAll('[data-page]').forEach(b=>{if(b.dataset.page===name)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});window.scrollTo({top:0})}
function showAuth(error=''){
 page('auth');const signup=authMode==='signup';
 $('#auth').innerHTML=`<div class="eyebrow">A LITTLE MORE CURIOUS</div><h1>Fancy knowing<br><em>something new?</em></h1><p class="intro">A little discovery, at your own pace.<br>Your discoveries, saved just for you.</p><div class="auth-tabs"><button id="loginmode" aria-pressed="${!signup}">Sign in</button><button id="signupmode" aria-pressed="${signup}">Create account</button></div><form id="authform" class="authform"><label>Email address<input class="field" id="identity" type="email" autocomplete="username" autocapitalize="none" spellcheck="false" maxlength="254" required></label><label>Password<span class="secret-field"><input class="field" id="password" type="password" autocomplete="${signup?'new-password':'current-password'}" maxlength="200" required aria-label="Password"><button class="secret-toggle" type="button" data-reveal="password" data-reveal-label="password" aria-controls="password" aria-label="Show password" aria-pressed="false"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/><path class="secret-slash" d="m3 3 18 18"/></svg><span>Show</span></button></span></label>${signup?'<label>Invitation code<span class="secret-field"><input class="field" id="code" type="password" autocomplete="off" maxlength="200" required aria-label="Invitation code"><button class="secret-toggle" type="button" data-reveal="code" data-reveal-label="invitation code" aria-controls="code" aria-label="Show invitation code" aria-pressed="false"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/><path class="secret-slash" d="m3 3 18 18"/></svg><span>Show</span></button></span></label><p class="smallnote">A simple password is fine.</p>':''}<p class="error" role="alert" id="autherror">${esc(error)}</p><button class="primary" id="authsubmit">${signup?'Create my account':'Welcome back'}</button></form>${!signup?`<button class="textbtn" id="forgot">Forgot password?</button>`:''}`;
 $('#loginmode').onclick=()=>{authMode='login';showAuth()};$('#signupmode').onclick=()=>{authMode='signup';showAuth()};
 if($('#forgot'))$('#forgot').onclick=()=>showForgot();
 $('#authform').onsubmit=async e=>{e.preventDefault();const button=$('#authsubmit');button.disabled=true;$('#autherror').textContent='';try{const data=await api('/auth/'+(signup?'signup':'login'),{method:'POST',body:{email:$('#identity').value.trim(),password:$('#password').value,...(signup?{code:$('#code').value}:{})}});user=data.user;applyTheme(user.settings.theme||theme);$('#auth').innerHTML='';await afterSignIn()}catch(err){if($('#autherror'))$('#autherror').textContent=err.message}finally{if($('#authsubmit'))$('#authsubmit').disabled=false}};
}
async function afterSignIn(){
 if(!user.email)return showEmailSetup(true);
 if(!user.profile?.onboardingComplete)return showOnboarding();
 await loadToday(requestedSlot,requestedDay);requestedSlot=0;requestedDay=null;
}
function showForgot(){
 page('auth');$('#auth').innerHTML=`<div class="eyebrow">LET’S GET YOU BACK IN</div><h1>Forgot your<br><em>password?</em></h1><p class="intro">Enter the email you use for Fancy Knowing. We’ll send you a link to choose a new password.</p><form class="authform" id="forgotform"><label>Email address<input class="field" id="recoveryemail" type="email" autocomplete="email" maxlength="254" value="${esc(user?.email||'')}" required></label><p class="error" id="recoveryerror" role="alert"></p><button class="primary" id="recoverybutton">Send reset link</button></form><p id="recoverysuccess" class="intro" role="status"></p><button class="textbtn" id="backlogin">Back to sign in</button>`;
 $('#backlogin').onclick=()=>{authMode='login';showAuth()};$('#forgotform').onsubmit=async e=>{e.preventDefault();$('#recoverybutton').disabled=true;$('#recoveryerror').textContent='';$('#recoverysuccess').textContent='';try{const data=await api('/auth/forgot-password',{method:'POST',body:{email:$('#recoveryemail').value.trim()}});$('#recoverysuccess').textContent=data.message;$('#recoverybutton').textContent='Send another link'}catch(err){$('#recoveryerror').textContent=err.message}finally{if($('#recoverybutton'))$('#recoverybutton').disabled=false}};
}
function showReset(){
 page('auth');$('#auth').innerHTML=`<div class="eyebrow">A FRESH START</div><h1>A new<br><em>password.</em></h1><p class="intro">Choose a password you’ll remember.</p><form class="authform" id="resetform"><label>New password<span class="secret-field"><input class="field" id="newpassword" type="password" autocomplete="new-password" maxlength="200" required aria-label="New password"><button class="secret-toggle" type="button" data-reveal="newpassword" data-reveal-label="new password" aria-controls="newpassword" aria-label="Show new password" aria-pressed="false"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/><path class="secret-slash" d="m3 3 18 18"/></svg><span>Show</span></button></span></label><label>Repeat password<span class="secret-field"><input class="field" id="repeatpassword" type="password" autocomplete="new-password" maxlength="200" required aria-label="Repeat password"><button class="secret-toggle" type="button" data-reveal="repeatpassword" data-reveal-label="repeat password" aria-controls="repeatpassword" aria-label="Show repeat password" aria-pressed="false"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/><path class="secret-slash" d="m3 3 18 18"/></svg><span>Show</span></button></span></label><p class="error" id="reseterror" role="alert"></p><button class="primary" id="resetbutton">Save password</button></form><button class="textbtn" id="newresetlink">Request a new link</button>`;
 $('#newresetlink').onclick=showForgot;$('#resetform').onsubmit=async e=>{e.preventDefault();$('#reseterror').textContent='';if($('#newpassword').value!==$('#repeatpassword').value){$('#reseterror').textContent='Those passwords do not match.';return}$('#resetbutton').disabled=true;try{const data=await api('/auth/reset-password',{method:'POST',body:{token:resetToken,password:$('#newpassword').value}});resetToken=null;clearAccount();authMode='login';showAuth();toast(data.message)}catch(err){$('#reseterror').textContent=err.message}finally{if($('#resetbutton'))$('#resetbutton').disabled=false}};
}
function showEmailSetup(canSkip=false){
 page('emailsetup');$('#emailsetup').innerHTML=`<div class="eyebrow">YOUR ACCOUNT, ALL TOGETHER</div><h1>Let’s add<br><em>your email.</em></h1><p class="intro">Keep your existing discoveries and use email to sign in or recover your password.</p><form class="authform" id="emailform"><label>Email address<input class="field" id="linkemail" type="email" autocomplete="email" value="${esc(user.email||'')}" maxlength="254" required></label><label>Current password<span class="secret-field"><input class="field" id="linkpassword" type="password" autocomplete="current-password" maxlength="200" required aria-label="Current password"><button class="secret-toggle" type="button" data-reveal="linkpassword" data-reveal-label="current password" aria-controls="linkpassword" aria-label="Show current password" aria-pressed="false"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/><path class="secret-slash" d="m3 3 18 18"/></svg><span>Show</span></button></span></label><p class="error" id="emailerror" role="alert"></p><button class="primary" id="linkbutton">Send confirmation link</button></form><p class="intro" id="linksuccess" role="status"></p><button class="textbtn" id="skipemail">${canSkip?'Do this later':'Back to settings'}</button>`;
 $('#skipemail').onclick=()=>{if(canSkip){if(!user.profile?.onboardingComplete)showOnboarding();else loadToday()}else{page('settings');renderSettings()}};
 $('#emailform').onsubmit=async e=>{e.preventDefault();$('#linkbutton').disabled=true;$('#emailerror').textContent='';try{const data=await api('/account/email',{method:'POST',body:{email:$('#linkemail').value.trim(),password:$('#linkpassword').value}});$('#linksuccess').textContent=data.message;$('#linkpassword').value=''}catch(err){$('#emailerror').textContent=err.message}finally{if($('#linkbutton'))$('#linkbutton').disabled=false}};
}
async function showOnboarding(edit=false,topicsOnly=false){
 profileEditing=edit;editingTopicsOnly=topicsOnly;page('onboarding');$('#onboarding').innerHTML=loading('A little about you…');
 try{const data=await api('/topics');setupDraft={name:user.profile?.name||'',interests:[...(user.profile?.interests||[])],includeEverything:user.profile?.includeEverything===true||!user.profile?.interests?.length,subjects:data.subjects,custom:data.custom};if(topicsOnly)renderTopicsStep();else renderNameStep()}catch(err){$('#onboarding').innerHTML=`<p class="intro">${esc(err.message)}</p><button class="primary" id="retrysetup">Try again</button>`;$('#retrysetup').onclick=()=>showOnboarding(edit,topicsOnly)}
}
function renderNameStep(){
 $('#onboarding').innerHTML=`<div class="eyebrow">${profileEditing?'MAKE IT YOURS':'A QUICK HELLO · 1 OF 2'}</div><h1>What should<br><em>we call you?</em></h1><p class="intro">Just your first name, or whatever you like going by.</p><form id="nameform" class="authform"><label>Your name<input class="field" id="displayname" autocomplete="given-name" maxlength="60" value="${esc(setupDraft.name)}" required></label><button class="primary">Continue</button></form>${profileEditing?'<button class="textbtn" id="cancelprofile">Back to settings</button>':''}`;
 $('#nameform').onsubmit=e=>{e.preventDefault();const value=$('#displayname').value.trim();if(!value)return;setupDraft.name=value;renderTopicsStep()};if($('#cancelprofile'))$('#cancelprofile').onclick=()=>{page('settings');renderSettings()};
}
function renderTopicsStep(){
 const options=[...new Set([...setupDraft.subjects,...setupDraft.custom,...setupDraft.interests])];
 $('#onboarding').innerHTML=`<div class="eyebrow">${profileEditing?'YOUR INTERESTS':'FOLLOW YOUR CURIOSITY · 2 OF 2'}</div><h1>What catches<br><em>your interest?</em></h1><p class="intro">Pick what catches your interest, ${esc(setupDraft.name)}, or try a bit of everything. You can combine both.</p><button type="button" class="topicpill everything-pill" id="everything" aria-pressed="${setupDraft.includeEverything}">Tell me a bit about everything</button><p class="smallnote" id="mixhint">${setupDraft.includeEverything&&setupDraft.interests.length?'Mostly your chosen topics, with a discovery from elsewhere about one question in three.':'Choose specific topics below, explore everything, or mix both.'}</p><div class="topicgrid" aria-label="Choose your interests">${options.map((t,i)=>`<button type="button" class="topicpill" data-topic="${i}" aria-pressed="${setupDraft.interests.includes(t)}">${esc(t)}</button>`).join('')}</div><p class="smallnote" id="selectioncount" role="status">${setupDraft.interests.length} selected · choose up to 20</p><label class="customlabel" for="customtopic">Something more specific?</label><form class="customform" id="customform"><input class="field" id="customtopic" placeholder="Marine biology focused on sharks" aria-label="Your own learning topic" maxlength="120" required><button class="askbutton" id="addtopic">Add</button></form><p class="smallnote">Unusual interests welcome. We’ll check custom topics make sense as a subject to learn about.</p><p class="error" id="topicerror" role="alert"></p><button class="primary" id="finishprofile">${profileEditing?'Save my interests':setupDraft.interests.length?'Let’s get curious':'Give me a bit of everything'}</button><button class="textbtn" id="backname">${editingTopicsOnly?'Back to settings':'Back'}</button>`;
 $('#everything').onclick=()=>{setupDraft.includeEverything=!setupDraft.includeEverything;renderTopicsStep()};
 document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>{const topic=options[Number(b.dataset.topic)],i=setupDraft.interests.indexOf(topic);if(i>=0)setupDraft.interests.splice(i,1);else{if(setupDraft.interests.length>=20){toast('Choose up to 20 interests.');return}setupDraft.interests.push(topic)}b.setAttribute('aria-pressed',setupDraft.interests.includes(topic));$('#mixhint').textContent=setupDraft.includeEverything&&setupDraft.interests.length?'Mostly your chosen topics, with a discovery from elsewhere about one question in three.':'Choose specific topics below, explore everything, or mix both.';$('#selectioncount').textContent=`${setupDraft.interests.length} selected · choose up to 20`;$('#finishprofile').textContent=profileEditing?'Save my interests':setupDraft.interests.length?'Let’s get curious':'Give me a bit of everything'});
 $('#backname').onclick=editingTopicsOnly?()=>{page('settings');renderSettings()}:renderNameStep;$('#customform').onsubmit=async e=>{e.preventDefault();if(setupDraft.interests.length>=20){$('#topicerror').textContent='Unselect a topic before adding another.';return}$('#addtopic').disabled=true;$('#finishprofile').disabled=true;$('#backname').disabled=true;$('#addtopic').textContent='Checking…';$('#topicerror').textContent='';try{const data=await api('/topics',{method:'POST',body:{topic:$('#customtopic').value.trim()}});if(!setupDraft.custom.includes(data.topic))setupDraft.custom.push(data.topic);if(!setupDraft.interests.includes(data.topic))setupDraft.interests.push(data.topic);renderTopicsStep();toast('Topic added')}catch(err){$('#topicerror').textContent=err.message}finally{if($('#addtopic')){$('#addtopic').disabled=false;$('#addtopic').textContent='Add';$('#finishprofile').disabled=false;$('#backname').disabled=false}}};
 $('#finishprofile').onclick=async()=>{$('#finishprofile').disabled=true;$('#topicerror').textContent='';try{const data=await api('/profile',{method:'PUT',body:{name:setupDraft.name,interests:setupDraft.interests,includeEverything:setupDraft.includeEverything}});user.profile=data.profile;setupDraft=null;if(profileEditing){page('settings');renderSettings();toast('Interests saved · We’ll use these for your next new question.')}else await loadToday()}catch(err){if($('#topicerror'))$('#topicerror').textContent=err.message}finally{if($('#finishprofile'))$('#finishprofile').disabled=false}};
}
function dailyPicker(){return dailySlots.length>1?`<div class="daily-picker" aria-label="Today’s different questions"><p>Question ${activeSlot+1} of ${dailySlots.length}</p><div>${dailySlots.map(item=>`<button data-daily-slot="${item.slot}" aria-label="Question ${item.slot+1}${item.answered?', answered':''}" aria-pressed="${item.slot===activeSlot}" ${busy?'disabled':''}>${item.slot+1}${item.answered?'<span aria-hidden="true">✓</span>':''}</button>`).join('')}</div></div>`:''}
async function loadLibrary(){const data=await api('/library');library=data.questions;return library}
async function loadToday(slot=0,day=null){if(!Number.isInteger(slot))slot=0;page('today');$('#today').innerHTML=loading('Finding your little discovery…');try{const data=await api('/today?slot='+slot+(day?'&day='+encodeURIComponent(day):''));todayNeedsRefresh=false;dailySlots=data.slots||[{slot:0,id:data.question.id}];dailyDay=data.day||data.question.day;activeSlot=data.slot||0;current={...data.question,saved:data.saved};todayId=current.id;mode='choice';reviewing=false;await loadLibrary();await attachConversation(current);renderToday()}catch(e){if(!user)return;$('#today').innerHTML=`<h1>A little<br><em>patience.</em></h1><p class="intro" role="alert">${esc(e.message)}</p><button class="primary" id="retrytoday">Try again</button>`;$('#retrytoday').onclick=()=>loadToday(slot,day)}}
function dueQuestions(){return library.filter(q=>q.saved&&q.saved.due<=Date.now()&&q.id!==current?.id)}
function renderToday(){if(!current)return;const q=current,a=q.attempt,answered=!!a,saved=!!q.saved;const due=dueQuestions();
 $('#today').innerHTML=`<div class="eyebrow date"><span class="dot"></span>${reviewing?'A LITTLE REFRESHER':user.profile?.name?'A LITTLE DISCOVERY FOR '+esc(user.profile.name.toUpperCase()):'YOUR DAILY LITTLE DISCOVERY'}</div><h1>A little more<br><em>curious.</em></h1><p class="intro">${dailySlots.length>1?`${dailySlots.length} different questions today. One little discovery at a time.`:'One question. A new thing to know.'}<br>Stay for a moment, or follow the rabbit hole.</p>${!reviewing&&dailySlots.some(item=>item.id===q.id)?dailyPicker():''}${due.length&&!reviewing?`<button class="due" id="duereview">❤️ A saved discovery is ready to revisit</button>`:''}<article class="card"><div class="cardtop"><span class="topic">✧ ${esc(q.topic)}</span><div class="question-actions">${answered?`<button class="share-question" id="sharequestion" aria-label="Share question">${shareIcon}</button>`:''}<button class="save" id="save" aria-label="${saved?'Unsave':'Save'} question" aria-pressed="${saved}" ${busy?'disabled':''}>${heartIcon(saved)}</button></div></div><h2 class="question">${esc(q.q)}</h2>${!answered?`<div class="mode"><button id="choice" aria-pressed="${mode==='choice'}" ${busy?'disabled':''}>Choose an answer</button><button id="type" aria-pressed="${mode==='type'}" ${busy?'disabled':''}>Type my guess</button></div>`:''}<div class="answers">${mode==='choice'||answered?q.options.map((o,i)=>`<button class="answer ${answered&&i===q.correct?'correct':answered&&i===a.choice?'wrong':''}" data-answer="${i}" ${answered||busy?'disabled':''}><span class="letter">${answered&&i===q.correct?'✓':String.fromCharCode(65+i)}</span>${esc(o)}</button>`).join(''):`<form id="guessform"><input class="field" id="guess" placeholder="Your best guess…" aria-label="Your answer" required maxlength="150" ${busy?'disabled':''}><button class="primary" ${busy?'disabled':''}>${busy?'Checking…':'Check my answer'}</button></form>`}</div>${answered?`<div class="result" role="status"><strong>${a.correct?'You got it. ✨':'A new thing to know. ✧'}</strong>${a.typed?`<p class="smallnote">Your guess: ${esc(a.typed)}</p>`:''}<p>${esc(q.explanation)}</p><a href="${esc(q.source)}" target="_blank" rel="noopener noreferrer">Check the source</a></div>`:`<p class="smallnote" role="status">${busy?'Checking your guess…':'No timer. No pressure. Take a guess.'}</p>`}</article>${answered?`<button class="heartrow" id="saveagain" ${busy?'disabled':''}><span class="icon">${heartIcon(saved)}</span><span><strong>${saved?'In your saved discoveries':'Want this one to stick?'}</strong><small>${saved?'Your question and conversation, kept together.':'Save it, with your conversation, for another look.'}</small></span><span class="save-label">${saved?'Saved':'Save'}</span></button>${conversationSection(q)}<div class="sectionhead"><h2>Dive deeper</h2><span class="badge">Only if you’re curious</span></div><form class="customform questionask" id="askform"><input class="field" id="ownquestion" placeholder="Ask your own question…" aria-label="Ask your own question" maxlength="1500" required><button class="askbutton">Ask</button></form><div class="suggestions">${q.follow.map((f,i)=>`<button data-follow="${i}">${esc(f)}<span class="follow-plus" aria-hidden="true">+</span></button>`).join('')}</div><p class="done">That’s your little discovery. You can stop here.</p>`:''}${q.id!==todayId||reviewing?'<button class="textbtn" id="backtoday">Back to today’s question</button>':''}`;
 if($('#sharequestion'))$('#sharequestion').onclick=()=>showShare(q.id);if($('#continuechat'))$('#continuechat').onclick=()=>openChat();
 document.querySelectorAll('[data-daily-slot]').forEach(b=>b.onclick=()=>{if(!busy)loadToday(Number(b.dataset.dailySlot),dailyDay)});
 $('#save').onclick=toggleSave;if($('#saveagain'))$('#saveagain').onclick=toggleSave;
 if($('#choice'))$('#choice').onclick=()=>{mode='choice';renderToday()};if($('#type'))$('#type').onclick=()=>{mode='type';renderToday();$('#guess').focus()};
 document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answer({choice:Number(b.dataset.answer)}));
 if($('#guessform'))$('#guessform').onsubmit=e=>{e.preventDefault();answer({typed:$('#guess').value.trim()})};
 document.querySelectorAll('[data-follow]').forEach(b=>b.onclick=()=>openChat(q.follow[Number(b.dataset.follow)]));if($('#askform'))$('#askform').onsubmit=e=>{e.preventDefault();const text=$('#ownquestion').value.trim();if(text)openChat(text)};
 if($('#duereview'))$('#duereview').onclick=()=>review(due[0].id);if($('#backtoday'))$('#backtoday').onclick=loadToday;
}
async function answer(input){if(busy||!current)return;busy=true;const q=current,id=q.id,attemptId=crypto.randomUUID();renderToday();try{const data=await api(`/questions/${id}/answer`,{method:'POST',body:{...input,attemptId}});if(current?.id===id){const slot=dailySlots.find(item=>item.id===id);if(slot)slot.answered=true;current={...data.question,saved:q.saved?{due:Date.now()+(data.question.attempt.correct?14:7)*86400000}:null};await loadLibrary();await attachConversation(current)}}catch(e){toast(e.message)}finally{busy=false;if(user&&current?.id===id)renderToday()}}
async function toggleSave(){if(busy||!current)return;busy=true;const id=current.id;try{const data=await api(`/questions/${id}/save`,{method:'POST',body:{saved:!current.saved}});if(current?.id===id)current.saved=data.saved;await loadLibrary();toast(data.saved?'Saved · First refresher in 7 days':'Removed from saved discoveries')}catch(e){toast(e.message)}finally{busy=false;if(user&&current?.id===id)renderToday()}}
async function attachConversation(question){
 if(!question.attempt)return;
 const item=library.find(q=>q.id===question.id);if(item?.chatCount===0){question.conversation=[];return}
 try{const data=await api(`/questions/${question.id}/chat`);question.conversation=data.messages}catch{question.conversationUnavailable=true}
}
function conversationSection(q){
 if(q.conversationUnavailable)return '<p class="smallnote">Your conversation could not load. Open Dive deeper to try again.</p><button class="textbtn" id="continuechat">Open conversation</button>';
 if(!q.conversation?.length)return '';
 return `<details class="conversation-history" open><summary>Your conversation <span>${q.conversation.length} messages</span></summary><div class="saved-messages">${q.conversation.map(m=>`<div class="message ${m.role==='user'?'user':''}"><span class="sr-only">${m.role==='user'?'You':'Fancy Knowing'}: </span>${esc(m.content)}</div>`).join('')}</div><button class="textbtn" id="continuechat">Continue conversation</button></details>`;
}
async function openDiscovery(id,refresh=false){
 if(busy)return;page('today');$('#today').innerHTML=loading(refresh?'A little refresher…':'Opening your discovery…');
 try{const data=await api(`/questions/${id}${refresh?'?blind=1':''}`);current={...data.question,saved:library.find(q=>q.id===id)?.saved||null};reviewing=refresh;mode='choice';if(!refresh)await attachConversation(current);renderToday()}catch(e){toast(e.message);await loadToday()}
}
const review=id=>openDiscovery(id,true);
function renderBank(){
 const items=bankTab==='saved'?library.filter(q=>q.saved):library;
 $('#bank').innerHTML=`<div class="eyebrow">KEEP THE GOOD BITS</div><h1>Saved<br><em>discoveries.</em></h1><div class="tabbar"><button id="savedtab" aria-pressed="${bankTab==='saved'}">Saved</button><button id="historytab" aria-pressed="${bankTab==='history'}">History</button></div><p class="intro">${items.length} ${items.length===1?'discovery':'discoveries'}. Questions and conversations, together.</p>${items.length?items.map(q=>`<article class="bankitem"><span class="topic">${esc(q.topic)}</span><p>${esc(q.q)}</p><small>${q.saved?'Refresher '+(q.saved.due<=Date.now()?'due now':'on '+new Date(q.saved.due).toLocaleDateString('en-GB',{day:'numeric',month:'short'})):'Discovered '+esc(q.day)}${q.chatCount?` · ${q.chatCount} chat messages`:''}</small><button class="primary" data-discovery="${esc(q.id)}">View discovery</button>${q.attempt?`<button class="textbtn" data-review="${esc(q.id)}">Try remembering</button>`:''}</article>`).join(''):'<div class="empty"><span aria-hidden="true">❤️</span>'+(bankTab==='saved'?'Heart a question that catches your attention. Its conversation stays with it.':'Your answered questions will appear here.')+'</div>'}`;
 $('#savedtab').onclick=()=>{bankTab='saved';renderBank()};$('#historytab').onclick=()=>{bankTab='history';renderBank()};document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>review(b.dataset.review));document.querySelectorAll('[data-discovery]').forEach(b=>b.onclick=()=>openDiscovery(b.dataset.discovery));
}
function saveSettings(patch){const task=settingsSaveQueue.catch(()=>{}).then(async()=>{const data=await api('/settings',{method:'PUT',body:patch});if((user.settings.dailyAmount||1)!==(data.settings.dailyAmount||1))todayNeedsRefresh=true;user.settings=data.settings;applyTheme(data.settings.theme||theme);return data.settings});settingsSaveQueue=task;return task}
const clockIcon='<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></svg>';
function timeField(id,label,value){return `<div class="time-setting"><span id="${id}label">${label}</span><button class="time-trigger" type="button" data-time-target="${id}" aria-labelledby="${id}label ${id}display">${clockIcon}<span id="${id}display">${esc(value)}</span><span aria-hidden="true">⌄</span></button><input id="${id}" type="hidden" value="${esc(value)}"></div>`}
let timeTarget=null,timeHour='08',timeMinute='00';
function renderTimeOptions(){
 $('#timehours').innerHTML=Array.from({length:24},(_,i)=>String(i).padStart(2,'0')).map(hour=>`<button type="button" data-hour="${hour}" aria-pressed="${hour===timeHour}">${hour}</button>`).join('');
 $('#timeminutes').innerHTML=Array.from({length:60},(_,i)=>String(i).padStart(2,'0')).map(minute=>`<button type="button" data-minute="${minute}" aria-pressed="${minute===timeMinute}">${minute}</button>`).join('');
 $('#timepreview').textContent=timeHour+':'+timeMinute;
 document.querySelectorAll('[data-hour]').forEach(b=>b.onclick=()=>{timeHour=b.dataset.hour;document.querySelectorAll('[data-hour]').forEach(item=>item.setAttribute('aria-pressed',item===b));$('#timepreview').textContent=timeHour+':'+timeMinute});
 document.querySelectorAll('[data-minute]').forEach(b=>b.onclick=()=>{timeMinute=b.dataset.minute;document.querySelectorAll('[data-minute]').forEach(item=>item.setAttribute('aria-pressed',item===b));$('#timepreview').textContent=timeHour+':'+timeMinute});
}
function openTimePicker(id){timeTarget=id;[timeHour,timeMinute]=$('#'+id).value.split(':');$('#timetitle').textContent=$('#'+id+'label').textContent;renderTimeOptions();$('#timeDialog').showModal();requestAnimationFrame(()=>{$('#timehours [aria-pressed=true]').scrollIntoView({block:'center'});$('#timeminutes [aria-pressed=true]').scrollIntoView({block:'center'})})}
$('#canceltime').onclick=()=>$('#timeDialog').close();
$('#applytime').onclick=()=>{const input=$('#'+timeTarget);if(input){input.value=timeHour+':'+timeMinute;$('#'+timeTarget+'display').textContent=input.value;input.dispatchEvent(new Event('change',{bubbles:true}))}$('#timeDialog').close()};
function settingCard(id,icon,title,subtitle,body){return `<details class="setting-card" data-setting-card="${id}" ${settingsOpen.has(id)?'open':''}><summary><span class="setting-symbol" aria-hidden="true">${icon}</span><span><strong>${title}</strong><small>${subtitle}</small></span><span class="setting-chevron" aria-hidden="true">›</span></summary><div class="setting-body">${body}</div></details>`}
function accountAction(id,label,kind){
 const paths={name:'<path d="m15 4 5 5M4 20l4-1L20 7a2.8 2.8 0 0 0-4-4L4 15l-1 6Z"/>',email:'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="m4 7 8 6 8-6"/>',password:'<circle cx="8" cy="9" r="4"/><path d="m11 12 8 8m-4-4 3-3m-1 5 3-3"/>'};
 return `<button class="account-action" id="${id}"><span class="account-action-icon" aria-hidden="true"><svg viewBox="0 0 24 24">${paths[kind]}</svg></span><span>${label}</span><svg class="account-action-chevron" viewBox="0 0 24 24" aria-hidden="true"><path d="m9 5 7 7-7 7"/></svg></button>`;
}
function renderSettings(){
 renderHeaderProfile();
 const s=user.settings,c=FancyDesign.colours({...s,theme}),fonts=FancyDesign.fonts;
 const design=`<div class="setting"><label>Appearance<button class="theme-slider" id="settingsTheme" data-theme-slider role="switch" aria-checked="${theme==='dark'}" aria-label="Dark mode"><span class="theme-thumb" aria-hidden="true"></span><span class="theme-sun" aria-hidden="true"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/></svg></span><span class="theme-moon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M20.4 14A8.5 8.5 0 0 1 10 3.6 8.5 8.5 0 1 0 20.4 14Z"/></svg></span></button></label></div><div class="setting"><strong>Colours</strong><div class="colour-slots"><button class="colour-slot" id="editaccent"><i style="background:${c.accent}"></i>Accent</button><button class="colour-slot" id="editbackground"><i style="background:${c.background}"></i>Background</button></div><p>Set the colours for ${theme} mode. Light and dark keep their own palettes.</p></div><div class="setting"><strong>Your font</strong><div class="font-grid">${Object.entries(fonts).map(([key,font])=>`<button class="font-card" data-font="${key}" aria-pressed="${(s.font||'clean')===key}" style="font-family:${font.family.replaceAll('"','&quot;')}"><span>A little curious</span><small>${font.label}</small></button>`).join('')}</div><label class="range-label" for="fontSize">Overall font size <output id="fontSizeValue">${s.fontSize||100}%</output></label><input id="fontSize" type="range" min="75" max="160" step="5" value="${s.fontSize||100}"><div class="design-preview"><strong>A little more curious.</strong><br>A new thing to know, in your own style.</div><button class="textbtn" id="resetdesign">Reset design</button></div>`;
 const notifications=`<div class="setting"><label for="notificationsEnabled">Question notifications<input type="checkbox" id="notificationsEnabled" ${s.notificationsEnabled!==false?'checked':''}></label><p>Your preferences are saved. Phone delivery will be enabled in the Android app.</p></div><div class="setting"><label for="notificationMode">Timing<select id="notificationMode"><option value="fixed" ${s.notificationMode!=='random'?'selected':''}>Set time</option><option value="random" ${s.notificationMode==='random'?'selected':''}>Surprise me at random times</option></select></label>${s.notificationMode==='random'?`<p>A fresh random time each day, within your chosen window.</p><div class="notification-window">${timeField('randomStart','From',s.randomStart||'08:00')}${timeField('randomEnd','Until',s.randomEnd||'21:00')}</div><button class="textbtn" id="savewindow">Save time window</button><p id="windowerror" role="status"></p>`:`${timeField('time','First question at',s.time||'08:00')}`}</div><div class="setting"><label class="range-label" for="dailyAmount">Different questions per day <output id="dailyAmountValue">${s.dailyAmount||1}</output></label><input type="range" id="dailyAmount" min="1" max="10" step="1" value="${s.dailyAmount||1}"><p>${s.notificationMode==='random'?'Each notification opens a different question. Random times are spread through your chosen window.':'One different question per notification. Questions are spaced between the first time and the end of the day.'}</p></div>`;
 const questions=`<div class="setting"><strong>Your topics</strong><p>${user.profile?.interests?.length?user.profile.interests.map(esc).join(', ')+(user.profile.includeEverything?' · plus a bit of everything':''):'A bit of everything'}</p><button class="secondary-button" id="editprofile">Edit my topics</button></div><div class="setting"><label class="range-label" for="answerCount">Multiple-choice answers <output id="answerCountValue">${s.answerCount||4}</output></label><input id="answerCount" type="range" min="2" max="10" step="1" value="${s.answerCount||4}"><p>Default: 4. New questions will have your chosen number of options. Today’s question and saved questions keep their original options.</p></div>`;
 const picture=user.avatar?`<img class="avatar" src="${esc(user.avatar)}" alt="Your profile picture">`:`<span class="avatar" aria-label="No profile picture">${esc((user.profile?.name||'?').slice(0,1).toUpperCase())}</span>`;
 const account=`<div class="setting"><div class="avatar-row"><div>${picture}</div><div class="profile-details"><strong>${esc(user.profile?.name||'Your profile')}</strong><div class="picture-actions"><label class="picture-button picture-action" for="avatarfile">Change picture</label>${user.avatar?'<button class="picture-action" id="removeavatar">Remove picture</button>':''}</div><input class="sr-only" id="avatarfile" type="file" accept="image/jpeg,image/png,image/webp"></div></div><p id="avatarstatus" role="status"></p>${accountAction('editname','Change name','name')}</div><div class="setting"><strong>Email & password</strong><p class="account-email">${user.email?esc(user.email):'Your old username: '+esc(user.legacyUsername)}</p><div class="account-actions">${accountAction('editemail',user.email?'Change email':'Add email for recovery','email')}${user.email?accountAction('recoverfromsettings','Change password','password'):''}</div></div>`;
 $('#settings').innerHTML=`<div class="eyebrow">MAKE YOURSELF AT HOME</div><h1>Your kind<br><em>of curious.</em></h1>${settingCard('design','◉','Design','Colours, fonts & text size',design)}${settingCard('notifications','♧','Notifications','When & how often',notifications)}${settingCard('questions','✧','Question preferences','Topics & multiple-choice answers',questions)}${settingCard('account','☺','My account','Picture, name, email & password',account)}<div class="settings-savebar"><button class="primary" id="saveallsettings">Save settings</button><p id="settingssavestatus" role="status">Changes also save automatically.</p></div><button class="secondary-button settings-signout" id="logout">Sign out</button>`;
 document.querySelectorAll('[data-setting-card]').forEach(d=>d.ontoggle=()=>{if(d.open)settingsOpen.add(d.dataset.settingCard);else settingsOpen.delete(d.dataset.settingCard)});
 document.querySelectorAll('[data-time-target]').forEach(b=>b.onclick=()=>openTimePicker(b.dataset.timeTarget));
 $('#saveallsettings').onclick=async()=>{const button=$('#saveallsettings');button.disabled=true;$('#settingssavestatus').textContent='Saving…';try{const patch={fontSize:Number($('#fontSize').value),dailyAmount:Number($('#dailyAmount').value),answerCount:Number($('#answerCount').value),notificationsEnabled:$('#notificationsEnabled').checked,notificationMode:$('#notificationMode').value};for(const key of ['time','randomStart','randomEnd'])if($('#'+key))patch[key]=$('#'+key).value;await saveSettings(patch);$('#settingssavestatus').textContent='Settings saved.';toast('Settings saved')}catch(e){$('#settingssavestatus').textContent=e.message}finally{if($('#saveallsettings'))$('#saveallsettings').disabled=false}};
 $('#settingsTheme').onclick=()=>$('#theme').click();
 const openColours=target=>{FancyDesign.wheel($('#colourDialog'),{...s,theme},async patch=>{await saveSettings(patch);renderSettings()});if(target==='background')$('#colourDialog [data-colour="background"]').click()};$('#editaccent').onclick=()=>openColours('accent');$('#editbackground').onclick=()=>openColours('background');
 document.querySelectorAll('[data-font]').forEach(b=>b.onclick=async()=>{try{await saveSettings({font:b.dataset.font});renderSettings()}catch(e){toast(e.message)}});
 $('#fontSize').oninput=e=>{const fontSize=Number(e.target.value);$('#fontSizeValue').textContent=fontSize+'%';FancyDesign.apply({...s,theme,fontSize})};
 $('#fontSize').onchange=async e=>{try{await saveSettings({fontSize:Number(e.target.value)})}catch(err){applyTheme(theme);toast(err.message)}};
 $('#resetdesign').onclick=async()=>{try{await saveSettings({font:'clean',fontSize:100,accentDark:'#d8ac47',accentLight:'#d8ac47',backgroundDark:'#101426',backgroundLight:'#f8f5ed'});renderSettings();toast('Design reset')}catch(e){toast(e.message)}};
 for(const key of ['dailyAmount','answerCount']){$('#'+key).oninput=e=>$('#'+key+'Value').textContent=e.target.value;$('#'+key).onchange=async e=>{try{await saveSettings({[key]:Number(e.target.value)})}catch(err){toast(err.message);renderSettings()}}}
 $('#notificationsEnabled').onchange=async e=>{try{await saveSettings({notificationsEnabled:e.target.checked})}catch(err){toast(err.message);renderSettings()}};
 $('#notificationMode').onchange=async e=>{try{await saveSettings({notificationMode:e.target.value});renderSettings()}catch(err){toast(err.message);renderSettings()}};
 if($('#savewindow'))$('#savewindow').onclick=async()=>{const button=$('#savewindow');button.disabled=true;$('#windowerror').textContent='';try{await saveSettings({randomStart:$('#randomStart').value,randomEnd:$('#randomEnd').value});toast('Random time window saved')}catch(err){$('#windowerror').textContent=err.message}finally{button.disabled=false}};
 if($('#time'))$('#time').onchange=async e=>{if(!e.target.value)return;try{await saveSettings({time:e.target.value});toast('Notification time saved')}catch(err){toast(err.message);renderSettings()}};
 $('#editprofile').onclick=()=>showOnboarding(true,true);$('#editname').onclick=()=>showOnboarding(true);$('#editemail').onclick=()=>showEmailSetup(false);if($('#recoverfromsettings'))$('#recoverfromsettings').onclick=showForgot;
 $('#avatarfile').onchange=async e=>{const file=e.target.files[0];if(!file)return;$('#avatarstatus').textContent='Saving your picture…';try{const avatar=await resizeAvatar(file);const data=await api('/avatar',{method:'PUT',body:{avatar}});user.avatar=data.avatar;renderHeaderProfile();renderSettings();toast('Profile picture saved')}catch(err){$('#avatarstatus').textContent=err.message}};
 if($('#removeavatar'))$('#removeavatar').onclick=async()=>{try{await api('/avatar',{method:'DELETE'});user.avatar=null;renderHeaderProfile();renderSettings()}catch(e){toast(e.message)}};
 $('#logout').onclick=async()=>{try{await api('/auth/logout',{method:'POST',body:{}});clearAccount();showAuth()}catch(e){toast(e.message)}};
}
async function resizeAvatar(file){
 if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024)throw new Error('Choose a JPG, PNG or WebP smaller than 10 MB.');
 let image;try{image=await createImageBitmap(file)}catch{throw new Error('That picture could not be opened. Try another image.')}
 const canvas=document.createElement('canvas');canvas.width=canvas.height=160;const ctx=canvas.getContext('2d'),side=Math.min(image.width,image.height);ctx.fillStyle='#f8f5ed';ctx.fillRect(0,0,160,160);ctx.drawImage(image,(image.width-side)/2,(image.height-side)/2,side,side,0,0,160,160);image.close();return canvas.toDataURL('image/jpeg',.85);
}
let chatReveal=null,chatLoaded=false;
function stopChatReveal(){if(chatReveal)chatReveal.cancel()}
function nearChatBottom(){const box=$('#messages');return box.scrollHeight-box.scrollTop-box.clientHeight<90}
function showMessages({typingIndex=-1,preserveScroll=false,pending=chatBusy}={}){
 if(!$('#chat').open)return;
 const box=$('#messages'),oldTop=box.scrollTop,follow=!preserveScroll||nearChatBottom();
 box.innerHTML=chatMessages.map((m,i)=>`<div class="message ${m.role==='user'?'user':''}" data-message="${i}">${i===typingIndex?'':esc(m.content)}</div>`).join('')+(pending?'<div class="message thinking" role="status"><span class="thinking-dots" aria-hidden="true"><i></i><i></i><i></i></span><span class="sr-only">Thinking…</span></div>':'');
 if(!chatMessages.length&&!pending)box.innerHTML='<div class="message">Ask one small thing. We’ll keep the answer small, too.</div>';
 box.scrollTop=follow?box.scrollHeight:oldTop;$('#sendchat').disabled=chatBusy;$('#chatinput').disabled=chatBusy;
}
function revealChatReply(text,index){
 if(!$('#chat').open||matchMedia('(prefers-reduced-motion: reduce)').matches){showMessages({pending:false});return Promise.resolve()}
 showMessages({typingIndex:index,pending:false});const element=$('#messages').querySelector('[data-message="'+index+'"]');if(!element)return Promise.resolve();
 const parts=typeof Intl.Segmenter==='function'?Array.from(new Intl.Segmenter(undefined,{granularity:'grapheme'}).segment(text),part=>part.segment):Array.from(text);
 return new Promise(resolve=>{
  let frame=0,startTime=null,finished=false;const speed=Math.max(75,parts.length/3.5);
  element.classList.add('is-typing');
  const finish=()=>{if(finished)return;finished=true;cancelAnimationFrame(frame);element.textContent=text;element.classList.remove('is-typing');if(chatReveal===controller)chatReveal=null;resolve()};
  const controller={cancel:finish};chatReveal=controller;
  const step=now=>{
   if(!$('#chat').open){finish();return}if(startTime===null)startTime=now;
   const follow=nearChatBottom(),count=Math.min(parts.length,Math.max(1,Math.floor((now-startTime)*speed/1000)));
   element.textContent=parts.slice(0,count).join('');if(follow)$('#messages').scrollTop=$('#messages').scrollHeight;
   if(count===parts.length)finish();else frame=requestAnimationFrame(step);
  };
  frame=requestAnimationFrame(step);
 });
}
function syncChatViewport(){if(!$('#chat').open)return;const viewport=window.visualViewport;$('#chat').style.setProperty('--chat-height',(viewport?.height||window.innerHeight)+'px');$('#chat').style.setProperty('--chat-top',(viewport?.offsetTop||0)+'px')}
window.visualViewport?.addEventListener('resize',syncChatViewport);window.visualViewport?.addEventListener('scroll',syncChatViewport);window.addEventListener('resize',syncChatViewport);
async function loadChat(id){const data=await api(`/questions/${id}/chat`);if(chatId===id){chatMessages=data.messages;chatLoaded=true;showMessages()}}
async function openChat(suggestion){
 if(chatBusy)return;stopChatReveal();chatId=current.id;chatMessages=[];chatLoaded=false;$('#chaterror').textContent='';$('#chatannounce').textContent='';$('#chat').showModal();document.body.classList.add('chat-open');syncChatViewport();$('#messages').innerHTML=loading('Opening your conversation…');
 try{await loadChat(chatId);if(!$('#chat').open)return;if(suggestion)await sendChat(suggestion);else $('#chatinput').focus({preventScroll:true})}catch(e){$('#chaterror').textContent=e.message}
}
async function sendChat(text){
 if(chatBusy||!text.trim())return;const id=chatId;chatBusy=true;$('#chaterror').textContent='';$('#chatannounce').textContent='';chatMessages.push({role:'user',content:text});$('#chatinput').value='';showMessages();
 try{const data=await api(`/questions/${id}/chat`,{method:'POST',body:{message:text}});if(chatId===id){chatMessages.push({role:'assistant',content:data.reply});if(current?.id===id){current.conversation=[...chatMessages];const item=library.find(q=>q.id===id);if(item)item.chatCount=chatMessages.length;if(!$('#chat').open)renderToday()}await revealChatReply(data.reply,chatMessages.length-1);if($('#chat').open)$('#chatannounce').textContent=data.reply}}
 catch(e){if(chatId===id){chatMessages.pop();$('#chatinput').value=text;$('#chaterror').textContent=e.message}}
 finally{chatBusy=false;if(chatId===id){showMessages({preserveScroll:true});if($('#chat').open)$('#chatinput').focus({preventScroll:true})}}
}
$('#chatform').onsubmit=e=>{e.preventDefault();sendChat($('#chatinput').value.trim())};$('#closechat').onclick=()=>$('#chat').close();
$('#chat').addEventListener('close',()=>{stopChatReveal();document.body.classList.remove('chat-open');$('#chatannounce').textContent='';if(chatLoaded&&current?.id===chatId&&current.attempt){current.conversation=[...chatMessages];current.conversationUnavailable=false;renderToday()}});
$('#theme').onclick=async()=>{const previous=theme;applyTheme(theme==='dark'?'light':'dark');if(user){try{const data=await api('/settings',{method:'PUT',body:{theme}});user.settings=data.settings}catch(e){applyTheme(previous);toast(e.message)}if(!$('#settings').hidden)renderSettings()}};
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=async()=>{if(!user)return;const p=b.dataset.page;if(p==='today'){if(current&&!todayNeedsRefresh){page('today');renderToday()}else await loadToday(activeSlot<(user.settings.dailyAmount||1)?activeSlot:0)}if(p==='settings'){page('settings');renderSettings()}if(p==='bank'){page('bank');$('#bank').innerHTML=loading('Opening your collection…');try{await loadLibrary();renderBank()}catch(e){toast(e.message)}}});
async function showShare(id){
 const dialog=$('#shareDialog');$('#shareurl').value='';$('#sharestatus').textContent='Preparing your link…';$('#copyshare').disabled=true;$('#nativeshare').hidden=!navigator.share;$('#nativeshare').disabled=true;dialog.showModal();
 try{const data=await api(`/questions/${id}/share`,{method:'POST',body:{}});if(!dialog.open)return;$('#shareurl').value=data.url;$('#sharestatus').textContent='';$('#copyshare').disabled=false;$('#nativeshare').disabled=false}catch(e){$('#sharestatus').textContent=e.message}
}
$('#closeshare').onclick=()=>$('#shareDialog').close();
$('#copyshare').onclick=async()=>{try{await navigator.clipboard.writeText($('#shareurl').value);$('#sharestatus').textContent='Link copied.'}catch{$('#shareurl').focus();$('#shareurl').select();$('#sharestatus').textContent='Select and copy the link above.'}};
$('#nativeshare').onclick=async()=>{try{await navigator.share({title:'Fancy knowing the answer?',url:$('#shareurl').value})}catch(e){if(e.name!=='AbortError')$('#sharestatus').textContent='Try copying the link instead.'}};
async function loadGuest(){
 document.body.classList.add('guest-view');page('today');$('#theme').hidden=true;$('#today').innerHTML=loading('Opening a shared discovery…');
 try{const data=await api('/shared/'+encodeURIComponent(guestToken));guestQuestion=data.question;renderGuest()}catch(e){$('#today').innerHTML=`<h1>A little<br><em>hiccup.</em></h1><p class="intro" role="alert">${esc(e.message)}</p>`}
}
function renderGuest(error=''){
 const q=guestQuestion,answered=!!q.attempt;
 $('#today').innerHTML=`<div class="eyebrow">A DISCOVERY SHARED WITH YOU</div><p class="intro">Fancy knowing the answer? Take a guess.</p><article class="card"><span class="topic">${esc(q.topic)}</span><h1 class="question">${esc(q.q)}</h1><div class="answers">${q.options.map((option,i)=>`<button class="answer ${answered&&i===q.correct?'correct':answered&&i===q.attempt.choice?'wrong':''}" data-guest-answer="${i}" ${guestBusy||answered?'disabled':''}><span class="letter">${answered&&i===q.correct?'✓':String.fromCharCode(65+i)}</span>${esc(option)}</button>`).join('')}</div>${answered?`<div class="result" role="status"><strong>${q.attempt.correct?'You got it.':'A new thing to know.'}</strong><p>${esc(q.explanation)}</p></div>`:`<p class="smallnote">${guestBusy?'Checking your guess…':'No account needed. Just a little curiosity.'}</p>`}<p class="error" role="alert">${esc(error)}</p></article>`;
 document.querySelectorAll('[data-guest-answer]').forEach(button=>button.onclick=()=>answerGuest(Number(button.dataset.guestAnswer)));
}
async function answerGuest(choice){
 if(guestBusy||guestQuestion.attempt)return;guestBusy=true;renderGuest();let error='';
 try{const data=await api(`/shared/${encodeURIComponent(guestToken)}/answer`,{method:'POST',body:{choice}});guestQuestion=data.question}catch(e){error=e.message}finally{guestBusy=false;renderGuest(error)}
}
$('#headerprofile').onclick=()=>{if(!user)return;settingsOpen.add('account');page('settings');renderSettings();$('#settings [data-setting-card=account]').scrollIntoView({behavior:'smooth',block:'start'})};
applyTheme(theme);
(async()=>{
 const params=new URLSearchParams(location.search);requestedSlot=/^[0-9]$/.test(params.get('slot')||'')?Number(params.get('slot')):0;requestedDay=params.get('day');guestToken=params.get('share');if(guestToken!==null){await loadGuest();return}resetToken=params.get('reset');const verifyToken=params.get('verify');
 if(resetToken||verifyToken)history.replaceState(null,'',location.pathname);
 if(resetToken){showReset();return}
 if(verifyToken){page('auth');$('#auth').innerHTML=loading('Confirming your email…');try{const result=await api('/auth/confirm-email',{method:'POST',body:{token:verifyToken}});toast(result.message)}catch(e){showAuth(e.message);return}}
 try{const data=await api('/me');user=data.user;applyTheme(user.settings.theme||theme);await afterSignIn()}catch(e){showAuth(e.status===401?'':e.message)}
})();

// Delegate so every dynamically rendered password/code field has the same control.
document.addEventListener('click',event=>{
 const button=event.target.closest?.('button[data-reveal]');if(!button)return;
 const input=document.getElementById(button.dataset.reveal);if(!input)return;
 const show=input.type==='password';input.type=show?'text':'password';
 button.setAttribute('aria-pressed',String(show));
 button.setAttribute('aria-label',(show?'Hide ':'Show ')+button.dataset.revealLabel);
 button.querySelector('span').textContent=show?'Hide':'Show';
});
